from collections import Counter

def solution(s, t):
    # Try every start; extend the end until the window covers t. O(n^2).
    best = None
    for i in range(len(s)):
        need = Counter(t)
        missing = len(t)
        for j in range(i, len(s)):
            if need[s[j]] > 0:
                missing -= 1
            need[s[j]] -= 1
            if missing == 0:
                if best is None or j - i + 1 < len(best):   # strict: leftmost wins ties
                    best = s[i:j + 1]
                break
    return best if best is not None else ""
